import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"kiwa","text":"OSS test framework","tagline":"dApps + web apps + full-stack frameworks + polyglot (TypeScript / Rust / Go / Python). One toolchain, every layer.","actions":[{"theme":"brand","text":"Get started (5-min tutorial)","link":"/tutorials/01-supabase-auth-first-test"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/cardene777/kiwa"}]},"features":[{"title":"30 skills, one workflow","details":"/kiwa-design → /kiwa-forge / /kiwa-hardhat / /kiwa-play / /kiwa-vitest / /kiwa-rust / /kiwa-go / /kiwa-auth / /kiwa-queue / /kiwa-cache → /kiwa-review. Layer 1 spec + Layer 2 code generation + Layer 3 verification, all under version control."},{"title":"11-axis release gate (v1.12)","details":"7 common axes (coverage + test count + fidelity + perf p95 + mutation) plus 4 AI-LLM axes (cost + latency + token + accuracy) — the AI-LLM branch activates automatically when the provider prefix matches @kiwa/ai-*. Release when the gate says PASS."},{"title":"Real-vs-mock dogfood","details":"Every provider has an example that runs against the real service AND against the kiwa mock. Divergences feed the fidelity axis of the release gate. AI-LLM providers (Anthropic + OpenAI + Vercel AI SDK + LangChain) joined in v1.12; realtime providers (Supabase Realtime + Ably + Pusher + Socket.io) join in v1.13."},{"title":"Polyglot from day 1","details":"TypeScript, Rust, Go, Python, Solidity — the same test skill chain drives all five languages."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function o(l,e,n,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h2 id="what-is-kiwa" tabindex="-1">What is kiwa? <a class="header-anchor" href="#what-is-kiwa" aria-label="Permalink to &quot;What is kiwa?&quot;">​</a></h2><p>kiwa is an OSS test framework that treats &quot;writing tests for a modern app&quot; as a workflow instead of a menu. One kiwa install gives you:</p><ul><li><strong>23 TypeScript packages</strong> — <code>@kiwa/{core,dapp,api,ui,data,e2e,a11y,visual,cli-test,observability,nextjs,nuxt,sveltekit,remix,astro,solidstart,qwikcity,edge,orm,auth,queue,cache,quality-metrics}</code></li><li><strong>1 Rust crate</strong> — <code>kiwa-test-rs</code> with <code>contract::foundry</code> + <code>contract::alloy</code> + axum + actix + tower-http adapters</li><li><strong>1 Go module</strong> — <code>kiwa-test-go</code> (gin / echo / fiber / net/http/httptest / testing.T)</li><li><strong>1 Python distribution</strong> — <code>kiwa-test-py</code> for pytest</li><li><strong>30 skills</strong> — reusable prompts that turn requirements into tests</li></ul><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa/auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span></span></code></pre></div><p>Then read <a href="/kiwa/tutorials/01-supabase-auth-first-test">Your first Supabase Auth test in 5 min</a>.</p><h2 id="latest-release" tabindex="-1">Latest release <a class="header-anchor" href="#latest-release" aria-label="Permalink to &quot;Latest release&quot;">​</a></h2><p><strong>v1.13 — Realtime + perf harness</strong> (2026-07-03).</p><ul><li><code>@kiwa/realtime</code> v0.1 — new package with unified mocks for Supabase Realtime + Ably + Pusher + Socket.io / SSE, plus a real-vs-mock fidelity harness scoped to 5 realtime scenarios (chat broadcast, presence join/leave, postgres CDC, room subscribe race, reconnect with pending)</li><li><code>@kiwa/perf-harness</code> v0.1 — new package with a 5-target perf benchmark helper (p50 / p95 / p99 + regression detection) feeding the release gate&#39;s <code>perf.p95Ms</code> axis</li><li>3 dogfood apps under <code>examples/dogfood-{supabase-realtime-chat,ably-collab-cursor,socketio-notification}/</code></li><li>New tutorials 09 – 11 + concept doc <a href="/kiwa/concepts/realtime-testing"><code>realtime-testing.md</code></a> + <a href="/kiwa/migrations/v1.12-to-v1.13">migration guide</a></li></ul><p>See the <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">Roadmap</a> for full milestone details.</p><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Status</th><th>Focus</th></tr></thead><tbody><tr><td>v1.9</td><td>✅</td><td>Multi-provider baseline</td></tr><tr><td>v1.10</td><td>✅</td><td>Supabase Auth + RabbitMQ + Rust contract layer</td></tr><tr><td>v1.11</td><td>✅</td><td>Quality metrics harness + dogfood app pattern + GitHub Pages</td></tr><tr><td>v1.12</td><td>✅</td><td>AI-LLM axis expansion — 11-axis release gate + <code>@kiwa/ai-llm</code> + 3 dogfood apps</td></tr><tr><td>v1.13</td><td>✅ 6/6</td><td>Realtime + perf harness — <code>@kiwa/realtime</code> v0.1 (4 provider mocks + fidelity harness) + <code>@kiwa/perf-harness</code> v0.1 + 3 dogfood apps (chat / cursor / notification)</td></tr></tbody></table>',12)])])}const k=t(r,[["render",o]]);export{u as __pageData,k as default};
